### FUNCION: openModal
```js
function openModal(cardId, currentStatus) {
    const modal = document.getElementById('card-modal');
    const form = document.getElementById('card-form');
    const titleInput = document.getElementById('title-input');
    const bodyInput = document.getElementById('body-input');
    const priorityInput = document.getElementById('priority-input');
    const cardIdInput = document.getElementById('card-id-input');
    const currentStatusInput = document.getElementById('current-status-input');
    const modalTitle = document.getElementById('modal-title');

    form.reset();
    cardIdInput.value = '';
    currentStatusInput.value = currentStatus;

    if (cardId) {
        // Editing existing card
        const card = findCardById(cardId);
        if (!card) return;

        modalTitle.textContent = 'Editar Tarjeta';
        titleInput.value = card.title;
        bodyInput.value = card.body;
        priorityInput.value = card.priority || ''; // Set existing priority
        cardIdInput.value = cardId;
    } else {
        // Creating new card
        modalTitle.textContent = 'Crear Nueva Tarjeta';
        // Default priority to media or leave blank if preferred, but setting it helps testing
        priorityInput.value = 'media'; 
    }

    modal.classList.remove('hidden');
    document.body.style.overflow = 'hidden';
}
