function handleCardSubmit(event) {
    event.preventDefault();

    const titleInput = document.getElementById('title-input').value;
    const bodyInput = document.getElementById('body-input').value;
    const priorityInput = document.getElementById('priority-input').value; // Get priority value
    const cardIdInput = document.getElementById('card-id-input').value;
    const currentStatusInput = document.getElementById('current-status-input').value;

    let cardData = {
        title: titleInput,
        body: bodyInput,
        priority: priorityInput, // Include priority in data
        status: currentStatusInput
    };

    if (cardIdInput) {
        // Editing existing card
        const cardIndex = findCardIndexById(cardIdInput.value);
        if (cardIndex !== -1) {
            let cardToUpdate = boardCards[cardIndex];
            Object.assign(cardToUpdate, cardData); // Update properties
            saveBoard();
            renderAllCards();
            closeModal();
            updateAllCounters();
            return;
        } else {
            alert('Error: No se encontró la tarjeta para editar.');
            return;
        }
    } else {
        // Creating new card
        const newCard = {
            id: Date.now().toString(), // Simple unique ID generation
            title: titleInput,
            body: bodyInput,
            priority: priorityInput, // Set priority for new card
            status: currentStatusInput
        };

        boardCards.push(newCard);
        saveBoard();
        renderAllCards();
        closeModal();
        updateAllCounters();
    }
}
