function createCardElement(card) {
    const cardDiv = document.createElement('div');
    cardDiv.className = 'card';
    cardDiv.setAttribute('draggable', true);
    cardDiv.dataset.id = card.id;
    cardDiv.innerHTML = `
        <div class="card-content">
            <h3>${card.title}</h3>
            <p>${card.body}</p>
            <div class="card-priority">Prioridad: <span class="priority-badge ${getPriorityClass(card.priority)}">${card.priority}</span></div>
        </div>
        <div class="card-actions">
            <button class="edit-btn action-btn" onclick="openModal('${card.id}', '${card.status}')">✏️ Editar</button>
            <button class="delete-btn action-btn" onclick="deleteCard('${card.id}', '${card.status}')">🗑️ Eliminar</button>
        </div>
    `;
    return cardDiv;
}
```

### FUNCION: getPriorityClass
```js
function getPriorityClass(priority) {
    switch (priority) {
        case 'alta':
            return 'high-priority'; // Rojo
        case 'media':
            return 'medium-priority'; // Amarillo
        case 'baja':
            return 'low-priority'; // Verde
        default:
            return '';
    }
}
